using namespace eternity;using namespace eternity::game;
namespace {
void require(bool value,const std::string& message) {if(!value) throw std::runtime_error(message);}
net::Packet unhex(const std::string& text) {net::Packet result;for(std::size_t i=0;i<text.size();i+=2) result.push_back(static_cast<std::uint8_t>(std::stoul(text.substr(i,2),nullptr,16)));return result;}
std::string hex(const auto& bytes) {constexpr char digits[]="0123456789abcdef";std::string result;for(auto b:bytes) {const auto c=static_cast<unsigned char>(b);result+=digits[c>>4];result+=digits[c&15];}return result;}
std::uint32_t get(const net::Packet& bytes,std::size_t at,unsigned int count) {std::uint32_t value=0;for(unsigned int i=0;i<count;++i) value|=static_cast<std::uint32_t>(bytes[at+i])<<(8*i);return value;}
PlayerCore load(std::uint32_t account,const net::Packet& bytes) {
    require(bytes.size()==99 && bytes.back()==0,"Invalid initial core payload");PlayerCore p;p.user_id=account;auto& c=p.character;
    c.id=get(bytes,0,4);c.slot=bytes[4];c.family=bytes[7];c.grow=bytes[8];c.hair=bytes[9];c.face=bytes[10];c.size=bytes[11];c.job=bytes[12];c.sex=bytes[13];c.level=static_cast<std::uint16_t>(get(bytes,14,2));p.stat_points=static_cast<std::uint16_t>(get(bytes,16,2));p.skill_points=static_cast<std::uint16_t>(get(bytes,18,2));p.experience=get(bytes,20,4);p.money=get(bytes,24,4);p.stored_money=get(bytes,28,4);
    for(std::size_t i=0;i<4;++i) p.kills[i]=get(bytes,32+4*i,4);p.kill_level=get(bytes,48,4);p.dead_level=get(bytes,52,4);c.map=static_cast<std::uint16_t>(get(bytes,56,2));p.direction=static_cast<std::uint16_t>(get(bytes,58,2));p.x=std::bit_cast<float>(get(bytes,60,4));p.y=std::bit_cast<float>(get(bytes,64,4));p.z=std::bit_cast<float>(get(bytes,68,4));p.hunger=static_cast<std::uint16_t>(get(bytes,72,2));p.vigor=std::bit_cast<std::int16_t>(static_cast<std::uint16_t>(get(bytes,74,2)));p.cg=bytes[76];p.og=bytes[77];p.ig=bytes[78];
    c.strength=static_cast<std::uint16_t>(get(bytes,80,2));c.dexterity=static_cast<std::uint16_t>(get(bytes,82,2));c.intelligence=static_cast<std::uint16_t>(get(bytes,84,2));c.wisdom=static_cast<std::uint16_t>(get(bytes,86,2));c.recovery=static_cast<std::uint16_t>(get(bytes,88,2));c.luck=static_cast<std::uint16_t>(get(bytes,90,2));c.hp=static_cast<std::uint16_t>(get(bytes,92,2));c.mp=static_cast<std::uint16_t>(get(bytes,94,2));c.sp=static_cast<std::uint16_t>(get(bytes,96,2));return p;
}
std::string snapshot(const CharacterReplica& cache) {
    std::ostringstream out;out<<"STATE "<<cache.body_changed()<<' '<<+cache.growth().maximum();
    for(bool bank:{false,true}) {const auto rows=bank?cache.inventory().bank():cache.inventory().inventory();out<<' '<<rows.size();for(const auto& row:rows) out<<' '<<(bank?row.item.slot:row.item.bag*24+row.item.slot)<<' '<<std::bit_cast<std::uint32_t>(row.save_type);}
    out<<' '<<cache.inventory().deleted_inventory().size()<<' '<<cache.inventory().deleted_bank().size()<<' '<<cache.skills().saved_count()<<' '<<cache.skills().reset_pending();
    for(const auto rows:{cache.quests().active(),cache.quests().finished()}) {out<<' '<<rows.size();for(const auto& row:rows) out<<' '<<row.save_type<<' '<<row.id;}
    out<<' '<<cache.quests().deleted().size();for(auto id:cache.quests().deleted()) out<<' '<<id;for(const auto& point:cache.interface().points()) out<<' '<<point.save_type;
    out<<' '<<cache.points().products()[239].save_type;const auto stored=cache.points().stored();const auto found=std::find_if(stored.begin(),stored.end(),[](const auto& p){return p.first==239;});out<<' '<<(found!=stored.end())<<' '<<(found!=stored.end()?found->second.save_type:0)<<' '<<cache.market().save_type();return out.str();
}
std::string encode(const RecoveryOperation& op) {
    std::string result=std::to_string(op.odbc)+' '+op.procedure;std::transform(result.begin(),result.end(),result.begin(),[](unsigned char c){return static_cast<char>(std::tolower(c));});
    for(std::size_t i=0;i<op.parameters.size();++i) {const auto& value=op.parameters[i];if(const auto number=std::get_if<std::int64_t>(&value)) result+=" i"+std::to_string(*number);else {const bool numeric=op.procedure=="usp_Save_Char_Info_E" && i>=17 && i<=19 || (op.procedure=="usp_Create_Char_SavePoint" || op.procedure=="usp_Save_Char_SavePoint") && i>=3;result+=' ';result+=numeric?'n':'s';result+=hex(std::get<std::string>(value));}}return result;
}
std::string read(const std::filesystem::path& path) {std::ifstream file(path,std::ios::binary);return {std::istreambuf_iterator<char>(file),{}};}
void filesystem_checks() {
    const auto directory=std::filesystem::temp_directory_path()/("eternity-recovery-"+std::to_string(std::chrono::steady_clock::now().time_since_epoch().count()));require(std::filesystem::create_directory(directory),"Cannot create private recovery fixture");struct Cleanup {std::filesystem::path path;~Cleanup(){std::error_code error;std::filesystem::remove_all(path,error);}} cleanup{directory};
    const auto path=directory/"characters.log";unsigned int clock_calls=0;CharacterRecoveryFile file(path,[&](){if(clock_calls++==1) {const auto partial=read(path);require(partial.starts_with("--<begin>") && partial.find("usp_Save_Char_QuickSlot_Del_E")!=std::string::npos && partial.find("--<end>")==std::string::npos,"Recovery lines were not flushed before end-record time");}return "2024-02-29 23:59:58";});InventoryReplicaPool pool;PlayerCore core;core.user_id=12345;core.character.id=17;core.character.name="RecoveryHero";CharacterReplica cache(core,pool);PlayerItem row;row.uid=1;row.id=5001;row.bag=1;row.type=5;row.type_id=1;row.make_type="U";require(cache.inventory().load(row,false,1),"Cannot seed recovery file item");const net::Packet body{0x15,6,0x39,0x30,0,0,1,2,3,1};require(cache.apply(body)==InventoryReplicaResult::applied,"Cannot seed recovery file body");
    auto result=file.append(cache,1,"recovery_user");require(result.legacy_success && result.persisted && result.operations==7 && !cache.body_changed() && cache.inventory().inventory()[0].save_type==0,"Recovery file did not capture/acknowledge original markers");result=file.append(cache,1,"recovery_user");require(result.persisted && result.operations==4,"Repeated file capture duplicated acknowledged phases");auto text=read(path);require(text.starts_with("--<begin>2024-02-29 23:59:58,recovery_user,12345,RecoveryHero,17\r\n") && text.ends_with("--<end>2024-02-29 23:59:58,recovery_user,12345,RecoveryHero,17\r\n\r\n\r\n"),"Recovery block markers/CRLF differ from original log formatter");
    CharacterReplica failed(core,pool);require(failed.apply(body)==InventoryReplicaResult::applied && failed.inventory().load(row,false,1),"Cannot seed failed file capture");CharacterRecoveryFile unavailable(directory,[]{return "2024-02-29 23:59:58";});result=unavailable.append(failed,1,"recovery_user");require(result.legacy_success && !result.persisted && !failed.body_changed() && failed.inventory().inventory()[0].save_type==0,"File open failure restored original cleared markers or changed legacy success");
    std::vector<std::future<void>> writers;for(std::uint32_t i=0;i<4;++i) writers.push_back(std::async(std::launch::async,[&,i](){InventoryReplicaPool own_pool;auto own=core;own.user_id+=i+1;own.character.id+=i+1;CharacterReplica owned(own,own_pool);require(file.append(owned,1,"concurrent").persisted,"Concurrent recovery write failed");}));for(auto& writer:writers) writer.get();text=read(path);std::size_t cursor=0,blocks=0;while(cursor<text.size()) {const auto begin=text.find("--<begin>",cursor);if(begin==std::string::npos) break;const auto end=text.find("--<end>",begin);require(end!=std::string::npos && text.find("--<begin>",begin+1)>end,"Recovery records interleaved");cursor=text.find("\r\n\r\n\r\n",end);require(cursor!=std::string::npos,"Incomplete recovery block terminator");cursor+=6;++blocks;}require(blocks==6,"Concurrent append lost recovery blocks");
}
}
int main(int argc,char** argv) {
    try {
        require(argc==2,"Expected original recovery oracle");std::ifstream input(argv[1]);require(input.good(),"Cannot open recovery oracle");InventoryReplicaPool pool;std::unique_ptr<CharacterReplica> cache;std::vector<RecoveryOperation> plan;std::size_t next=0,cases=0,saves=0,queries=0,metas=0;std::uint8_t server=0;std::string line;
        while(std::getline(input,line)) {
            if(line.empty() || line[0]=='#') continue;std::istringstream row(line);std::string tag;row>>tag;
            if(tag=="INIT") {std::uint32_t uid=0;unsigned int realm=0;std::string bytes;row>>uid>>realm>>bytes;auto packed=unhex(bytes);packed.push_back(0);auto core=load(uid,packed);core.character.name="RecoveryHero";cache=std::make_unique<CharacterReplica>(core,pool);cache->growth().load(packed[6]);server=static_cast<std::uint8_t>(realm);++cases;}
            else if(tag=="ITEM") {bool bank=false;std::size_t index=0;unsigned int type=0,tid=0,count=0,quality=0,make=0;std::int32_t save=0;std::string gems,craft;PlayerItem item;row>>bank>>index>>item.uid>>item.id>>type>>tid>>count>>quality>>gems>>craft>>item.made_at>>make>>save;item.bag=bank?0:static_cast<std::uint8_t>(index/24);item.slot=static_cast<std::uint16_t>(bank?index:index%24);item.type=static_cast<std::uint8_t>(type);item.type_id=static_cast<std::uint8_t>(tid);item.count=static_cast<std::uint8_t>(count);item.quality=static_cast<std::uint16_t>(quality);const auto bytes=unhex(gems);std::copy(bytes.begin(),bytes.end(),item.gems.begin());item.craft=craft=="-"?"":craft;if(make) item.make_type.assign(1,static_cast<char>(make));require(cache->inventory().load(item,bank,save),"Cannot seed recovery inventory row");}
            else if(tag=="SKILLS") {std::size_t n=0;row>>n;std::vector<PlayerSkill> learned;std::vector<PersistedEffect> effects;for(std::size_t i=0;i<n;++i) {unsigned int id=0,level=0,number=0,delay=0;row>>id>>level>>number>>delay;learned.push_back({static_cast<std::uint16_t>(id),static_cast<std::uint16_t>(delay),static_cast<std::uint8_t>(level),static_cast<std::uint8_t>(number),static_cast<std::uint8_t>(number)});}row>>n;for(std::size_t i=0;i<n;++i) {unsigned int id=0,level=0;std::uint32_t delay=0;row>>id>>level>>delay;effects.push_back({static_cast<std::uint16_t>(id),static_cast<std::uint8_t>(level),delay});}require(cache->skills().load(learned,effects),"Cannot seed recovery skills");}
            else if(tag=="RESET") {unsigned int points=0;row>>points;cache->skills().finish_reset(static_cast<std::uint16_t>(points));}
            else if(tag=="QUEST") {bool finished=false;unsigned int id=0,delay=0,success=0,a=0,b=0,c=0;row>>finished>>id>>delay>>success>>a>>b>>c;require(finished?cache->quests().load_finished({static_cast<std::uint16_t>(id),static_cast<std::uint8_t>(success)}):cache->quests().load({static_cast<std::uint16_t>(id),static_cast<std::uint16_t>(delay),{static_cast<std::uint8_t>(a),static_cast<std::uint8_t>(b),static_cast<std::uint8_t>(c)}}),"Cannot seed recovery quests");}
            else if(tag=="PRODUCT" || tag=="POINT") {unsigned int slot=0,count=0;std::uint32_t id=0;row>>slot>>id>>count;const std::array<PlayerPointItem,1> rows{{{static_cast<std::uint8_t>(slot),id,static_cast<std::uint8_t>(count)}}};if(tag=="PRODUCT") cache->points().load_products(rows);else cache->points().load_stored(rows);}
            else if(tag=="OP") {std::string packet;row>>packet;require(cache->apply(unhex(packet))==InventoryReplicaResult::applied,"Recovery fixture command was rejected");}
            else if(tag=="SAVE") {bool io=false,returned=false;row>>io>>returned;require(returned,"Original recovery unexpectedly failed on a valid user/log");plan=capture_character_recovery(*cache,server);next=metas=0;++saves;}
            else if(tag=="META") {std::string expected;row>>expected;const auto core=cache->core();const bool ending=metas++!=0;const auto text=std::string(ending?"--<end>":"--<begin>")+"2024-02-29 23:59:58,recovery_user,"+std::to_string(core.user_id)+",RecoveryHero,"+std::to_string(core.character.id)+(ending?"\r\n\r\n":"");require(hex(text)==expected,"Original recovery block metadata differs");}
            else if(tag=="QUERY") {require(next<plan.size(),"Original emitted an extra recovery statement");const auto actual=encode(plan[next++]);require(actual==line.substr(6),"Recovery SQL differs at save "+std::to_string(saves)+" statement "+std::to_string(next)+"\nactual: "+actual+"\nsource: "+line.substr(6));++queries;}
            else if(tag=="STATE") {const auto actual=snapshot(*cache);require(actual==line,"Recovery mutation differs at save "+std::to_string(saves)+"\nactual: "+actual+"\nsource: "+line);}
            else if(tag=="END") require(next==plan.size() && metas==2,"Native recovery coverage differs");
            else throw std::runtime_error("Unknown recovery oracle row");
        }
        require(cases==32 && saves==64 && queries==2172,"Recovery oracle coverage changed");filesystem_checks();std::cout<<saves<<" original full recovery captures and "<<queries<<" statements passed, including file failure and concurrent record appends\n";
    }catch(const std::exception& error) {std::cerr<<error.what()<<'\n';return 1;}
}
